import React from 'react';
import { CustomStyleIconType } from '../types';

const IslandParadise = ({ size }: CustomStyleIconType) => {
	return (
		<svg
			width={size}
			height={size}
			viewBox="0 0 24 25"
			fill="none"
			xmlns="http://www.w3.org/2000/svg"
		>
			<rect y="0.0192261" width="24" height="24" fill="url(#pattern0)" />
			<defs>
				<pattern
					id="pattern0"
					patternContentUnits="objectBoundingBox"
					width="1"
					height="1"
				>
					<use href="#image0_5448_857" transform="scale(0.0104167)" />
				</pattern>
				<image
					id="image0_5448_857"
					width="96"
					height="96"
					xlinkHref="data:image/png;base64,"
				/>
			</defs>
		</svg>
	);
};

export default IslandParadise;
